macro.command:
// RainbowSpray_Simplified_StrictA
(async () => {
  try {
    const a = args?.[0] ?? {};
    const item = a.item ?? a.itemData ?? null;
    const caster = a.actor ?? (a.token ? canvas.tokens.get(a.token.id)?.actor : undefined) ?? game.actors.get(a.actor?._id);
    const casterToken = canvas.tokens.get(a.token?.id) ?? canvas.tokens.controlled[0] ?? canvas.tokens.placeables.find(t => t.actor?.id === caster?.id);

    if (!caster) { ui.notifications.error("RainbowSpray: 無法找到施法者"); return true; }

    // 收集目標
    let targets = [];
    if (Array.isArray(a?.targets) && a.targets.length) targets = a.targets.map(t => canvas.tokens.get(t.id ?? t.document?.id)).filter(Boolean);
    else if (Array.isArray(a?.targetUuids) && a.targetUuids.length) {
      for (const u of a.targetUuids) { try { const d = await fromUuid(u); if (d?.documentName === "Token") targets.push(canvas.tokens.get(d.id)); } catch {} }
    } else targets = Array.from(game.user.targets);
    if (!targets.length) { ui.notifications.warn("RainbowSpray: 未選中目標"); return true; }

    // 計算 DC（優先 item/system/actor 的設定）
    const computeSpellDC = (actorObj, itemObj) => {
      try { if (itemObj?.system?.save?.dc) return Number(itemObj.system.save.dc); } catch {}
      try { const aDC = actorObj?.system?.attributes?.spell?.dc ?? actorObj?.system?.attributes?.spelldc; if (aDC) return Number(aDC); } catch {}
      const abil = itemObj?.system?.ability ?? Object.keys(actorObj.system.abilities)[0];
      const abilMod = Number(actorObj?.system?.abilities?.[abil]?.mod ?? 0);
      const prof = Number(actorObj?.system?.attributes?.prof ?? actorObj?.system?.attributes?.proficiency ?? 0);
      const itemBonus = Number(itemObj?.system?.save?.bonus ?? 0);
      return 8 + abilMod + prof + itemBonus;
    };
    const spellDC = computeSpellDC(caster, item);

    const colorMap = {
      1:{type:"fire",label:"紅 (fire)"},
      2:{type:"acid",label:"橙 (acid)"},
      3:{type:"lightning",label:"黃 (lightning)"},
      4:{type:"poison",label:"綠 (poison)"},
      5:{type:"cold",label:"藍 (cold)"},
      6:{type:"petrify",label:"靛 (petrify)"},
      7:{type:"blind",label:"紫 (blind)"},
      8:{type:"special",label:"特殊 (special)"}
    };

    // 全場一次 10d6
    const globalRoll = await new Roll("10d6").roll();
    const globalTotal = Number(globalRoll.total);
    await globalRoll.toMessage({ flavor: `虹光噴射 — 全場傷害擲骰 = ${globalTotal}` });

    // helper: roll d8 (special) 並公告
    const rollD8 = async tk => {
      let r = await new Roll("1d8").roll();
      if (r.total === 8) { r = await new Roll("1d8").roll(); if (r.total === 8) r = await new Roll("1d8").roll(); }
      ChatMessage.create({ content: `${tk.name} 被判定爲: <b>${(colorMap[r.total]?.label) ?? r.total}</b> (d8=${r.total})`, speaker: ChatMessage.getSpeaker({ actor: caster }) });
      return r.total;
    };

    // doDexSave（嚴格版：僅使用系統提供的豁免方法；若兩者都不存在則拋出）
    const doDexSave = async actorTarget => {
      if (typeof actorTarget.rollSavingThrow === "function") return await actorTarget.rollSavingThrow("dex", { fastForward: false, chatMessage: true });
      if (typeof actorTarget.rollAbilitySave === "function") return await actorTarget.rollAbilitySave("dex", { fastForward: false, chatMessage: true });
      console.error(`RainbowSpray: ${actorTarget.name} 不支持 rollSavingThrow/rollAbilitySave（嚴格模式）`);
      ChatMessage.create({ content: `RainbowSpray: 錯誤 — 目標 ${actorTarget.name} 不支持標準豁免方法，請檢查該 Actor 配置。` });
      throw new Error("Target actor lacks saving throw API");
    };

    // apply item AE to target (for petrify / blind)
    const applyItemAEToTarget = async (targetActor, keywords=[]) => {
      if (!item?.effects?.length) return false;
      const found = item.effects.find(ef => {
        const nm = String(ef.name ?? ef.label ?? ef.data?.name ?? "").toLowerCase();
        return keywords.some(k => nm.includes(k));
      });
      if (!found) return false;
      const data = found.toObject ? found.toObject() : duplicate(found);
      if (data._id) delete data._id;
      data.origin = a.uuid ?? a.itemUuid ?? item?.uuid ?? data.origin;
      await targetActor.createEmbeddedDocuments("ActiveEffect", [data]);
      return true;
    };

    // 主循環（嚴格/無回退）
    for (const tk of targets) {
      if (!tk?.actor) continue;
      const tgtActor = tk.actor;
      const d8 = await rollD8(tk);
      const color = colorMap[d8] ?? colorMap[8];

      // 強制使用系統豁免方法（嚴格）
      const save = await doDexSave(tgtActor);
      const saveTotal = Number(save?.total ?? save?.results?.[0]?.result ?? -9999);
      const saved = saveTotal >= spellDC;

      // petrify / blind: copy AE from item
      if (color.type === "petrify" || color.type === "blind") {
        if (!saved) {
          const ok = await applyItemAEToTarget(tgtActor, color.type === "petrify" ? ["petr","indigo"] : ["violet","blind"]);
          if (!ok) ChatMessage.create({ content: `${tgtActor.name} 未找到對應 AE（請在施法物品上添加）` });
          else ChatMessage.create({ content: `${tgtActor.name} 未通過豁免，已應用 ${color.label}` });
        } else {
          ChatMessage.create({ content: `${tgtActor.name} 豁免成功，未觸發 ${color.label}` });
        }
        continue;
      }

      // 普通傷害色（1-5）
      if (["fire","acid","lightning","poison","cold"].includes(color.type)) {
        const applied = saved ? Math.floor(globalTotal/2) : globalTotal;
        const typed = new Roll(`${applied}[${color.type}]`);
        if (typeof typed.evaluateSync === "function") typed.evaluateSync(); else await typed.roll();

        try {
          await new MidiQOL.DamageOnlyWorkflow(caster, casterToken, applied, color.type, [tk], typed, {
            flavor: `${item?.name ?? "Rainbow Spray"} — ${color.label}`,
            itemCardId: a.itemCardId ?? a.itemCardUUID ?? null,
            itemData: duplicate(item) ?? {},
            useOther: false
          });
          // 成功時正常繼續（不做其它回退）
        } catch (err) {
          console.error("RainbowSpray: DamageOnlyWorkflow failed for", tk.name, err);
          ChatMessage.create({ content: `自動應用傷害失敗：請 GM 手動應用 ${applied} ${color.type} 到 ${tk.name}` });
        }
      }
    }

    return true;
  } catch (e) {
    console.error("RainbowSpray strict error", e);
    return true;
  }
})();
